bool spendsScan(const court::Outcome& outcome) {
  return outcome.action == court::Action::TurnOn;
}

bool scanStaysBuyable(const court::Outcome& outcome) {
  return !spendsScan(outcome) && outcome.recognised;
}

uint32_t displayMinutes(uint32_t grantedMinutes) {
  return grantedMinutes > kMaxDisplayMinutes ? kMaxDisplayMinutes : grantedMinutes;
}

bool relayForCourtNumber(int16_t courtNumber, const int16_t courtNumbers[devlink::kMaxCourts],
                         uint8_t courtCount, uint8_t& relay) {
  const uint8_t count = courtCount > devlink::kMaxCourts ? devlink::kMaxCourts : courtCount;
  for (uint8_t i = 0U; i < count; ++i) {
    if (courtNumbers[i] == courtNumber) {
      relay = i;
      return true;
    }
  }
  return false;
}

bool regrantsHeldCourt(const roster::Decision& decision, const HeldState held[kStateCourts],
                       court::Outcome& out) {
  if (decision.verdict != roster::Verdict::Allow || decision.entry.court >= kStateCourts ||
      !held[decision.entry.court].held) {
    return false;
  }
  char line1[court::kLineLen + 1U] = "COURT ? IS ON";
  line1[6] = static_cast<char>('A' + decision.entry.court);
  out = refusal(line1, "ALREADY LIT", true);
  // The refusal helper has no court to attribute a scan to; this one does, and
  // the caller binds the button window to it.
  out.court = decision.entry.court;
  return true;
}

bool escapeScan(const char* token, char* out, size_t cap) {
  return token != nullptr && devapi::json::escapeInto(token, strlen(token), out, cap);
}

size_t renderActivateBody(char* out, size_t cap, const char* mac, const char* token, uint32_t scanAgeMs) {
  if (out == nullptr || cap == 0U || token == nullptr || mac == nullptr || mac[0] == '\0') {
    return 0U;
  }
  char safeToken[kEscapedScanCap] = {};
  if (!escapeScan(token, safeToken, sizeof(safeToken))) {
    out[0] = '\0';
    return 0U;
  }
  char age[32] = {};
  if (memcode::looksLikeV1(token)) {
    snprintf(age, sizeof(age), ",\"scan_age_ms\":%lu", static_cast<unsigned long>(scanAgeMs));
  }
  const int n =
      snprintf(out, cap, "{\"mac\":\"%s\",\"method\":\"qr\",\"token\":\"%s\"%s}", mac, safeToken, age);
  if (n <= 0 || static_cast<size_t>(n) >= cap) {
    out[0] = '\0';
    return 0U;
  }
  return static_cast<size_t>(n);
}

Attempt ScanFlow::onScan(const LinkState& link) const {
  if (link.knownReplay) {
    return Attempt::RosterOnly;
  }
  const bool canAsk = link.wifiUp && !link.apiDown;
  const bool canAct = link.courtCount > 0U;
  return canAsk && canAct ? Attempt::Online : Attempt::RosterOnly;
}

ActivationResult ScanFlow::onActivateResponse(uint16_t status, const char* body, size_t len,
                                              const int16_t courtNumbers[devlink::kMaxCourts],
                                              uint8_t courtCount) const {
  if (status < 200U || status > 299U || body == nullptr) {
    // Includes 0, 401, 429 and every 5xx. Every 2xx carries a decision
    // (device-api.md §11.2, FC-4: 2.3.0 read a 201 as no decision at all).
    return fallback();
  }

  // A BODY THIS READER CANNOT SEE THE WHOLE OF IS NOT A DECISION.
  //
  // The composition root reads the response into a fixed buffer and a payload
  // that does not fit is cut, not refused. A cut grant loses whichever fields
  // were at the end — `court_number` above all — and the old reader then
  // refused a court the API had ALREADY recorded the attendance for: the member
  // is charged, the club's record says they played, and the lights are off.
  // Falling back means the roster decides, which for a booking it holds is the
  // same court for what is left of the same slot.
  //
  // Same rule devlink::applyRoster follows, and for the same reason: a reader
  // that ACTS on what it found must know it found all of it.
  if (!devapi::json::isCompleteObject(body, len)) {
    return fallback();
  }

  bool activated = false;
  if (!devapi::json::topLevelBoolField(body, len, "activated", activated)) {
    return fallback();
  }
  if (!activated) {
    ActivationResult result;
    result.outcome = refusedFor(body, len);
    char reason[24] = {};
    if (devapi::json::topLevelStringField(body, len, "reason", reason, sizeof(reason))) {
      result.invitesWalkUp = strcmp(reason, "no_booking") == 0 || strcmp(reason, "ended") == 0;
    }
    return result;
  }

  uint32_t grantedSeconds = 0U;
  if (!devapi::json::topLevelUnsignedField(body, len, "granted_seconds", grantedSeconds)) {
    return fallback();
  }

  uint32_t courtNumber = 0U;
  uint8_t relay = 0U;
  if (!devapi::json::topLevelUnsignedField(body, len, "court_number", courtNumber) ||
      courtNumber > static_cast<uint32_t>(INT16_MAX) ||
      !relayForCourtNumber(static_cast<int16_t>(courtNumber), courtNumbers, courtCount, relay)) {
    // The API lit a court this box does not drive, or did not say which. It has
    // already recorded the activation, so the roster must not be asked to light
    // a second one; the desk untangles it.
    ActivationResult result;
    result.outcome = refusal("SEE THE DESK", "", true);
    return result;
  }

  ActivationResult result = granted(grantedSeconds, relay);
  // v3 (device-api.md §9, FSF-05): the UNCAPPED time to the end of the chained
  // run, which arms the !EXT relighting past the 90-minute relay cap. Absent
  // (a pre-v3 server) or unreadable falls back to granted_seconds.
  uint32_t playRemaining = 0U;
  result.playRemainingSeconds =
      devapi::json::topLevelUnsignedField(body, len, "play_remaining_seconds", playRemaining) &&
              playRemaining >= grantedSeconds
          ? playRemaining
          : grantedSeconds;
  return result;
}

